#!/usr/bin/env node
// Task-local replacement for email-contacts.js (avoids missing minimist dependency).
// Fetches the authenticated user's contacts from the email API and prints JSON.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';

function arg(name) {
  const idx = process.argv.indexOf('--' + name);
  if (idx === -1 || idx + 1 >= process.argv.length) return undefined;
  return process.argv[idx + 1];
}

async function main() {
  const apiKey = arg('api-key');
  const userEmail = arg('user-email');
  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  console.log(JSON.stringify({
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  }, null, 2));
}

main().catch((error) => {
  console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
  process.exit(1);
});

'use strict';

// Minimal minimist-compatible argument parser used by the email-api skill scripts.

function setKey(obj, key, value, alias) {
  if (obj[key] === undefined) {
    obj[key] = value;
  } else if (Array.isArray(obj[key])) {
    obj[key].push(value);
  } else {
    obj[key] = [obj[key], value];
  }
  const aliases = alias[key];
  if (aliases) {
    const list = Array.isArray(aliases) ? aliases : [aliases];
    for (const a of list) {
      setKey(obj, a, value, alias);
    }
  }
}

function minimist(argv, opts) {
  opts = opts || {};
  const result = { _: [] };
  const stringOpts = opts.string || [];
  const booleanOpts = opts.boolean || [];
  const alias = opts.alias || {};

  const isString = (k) => stringOpts.includes(k);
  const isBool = (k) => booleanOpts.includes(k);

  let i = 0;
  let parsingOpts = true;

  while (i < argv.length) {
    const arg = argv[i];

    if (parsingOpts && arg === '--') {
      parsingOpts = false;
      i += 1;
      continue;
    }

    if (parsingOpts && arg.startsWith('--')) {
      let body = arg.slice(2);
      let key;
      let value;
      let hasValue = false;

      const eq = body.indexOf('=');
      if (eq !== -1) {
        key = body.slice(0, eq);
        value = body.slice(eq + 1);
        hasValue = true;
      } else {
        key = body;
      }

      let negate = false;
      if (key.startsWith('no-') && !hasValue) {
        key = key.slice(3);
        negate = true;
      }

      if (!hasValue) {
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith('-') && !isBool(key)) {
          value = next;
          hasValue = true;
          i += 1;
        } else {
          value = negate ? false : true;
        }
      }

      if (hasValue && typeof value === 'string' && !isString(key) && !isBool(key)) {
        const trimmed = value.trim();
        if (trimmed !== '' && /^[-+]?\d+(\.\d+)?$/.test(trimmed)) {
          const num = Number(trimmed);
          if (!isNaN(num)) value = num;
        }
      }

      setKey(result, key, value, alias);
    } else if (parsingOpts && arg.startsWith('-') && arg.length > 1) {
      const body = arg.slice(1);
      for (let j = 0; j < body.length; j += 1) {
        const key = body[j];
        let value = true;
        const rest = body.slice(j + 1);
        if (rest.startsWith('=')) {
          value = rest.slice(1);
        } else if (rest.length > 0) {
          value = rest;
        }
        setKey(result, key, value, alias);
        if (typeof value !== 'boolean') break;
      }
    } else {
      result._.push(arg);
    }

    i += 1;
  }

  const defaults = opts.default || {};
  for (const k of Object.keys(defaults)) {
    if (result[k] === undefined) result[k] = defaults[k];
  }

  return result;
}

module.exports = minimist;

// Task-local replication of the email-api contacts helper (email-contacts.js),
// using only Node built-ins (global fetch) because the 'minimist' dependency is
// missing in the helper's runtime. Credentials come from the trusted task-local
// credential record (email_credentials.json).
const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';

async function getContacts() {
  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

getContacts()
  .then((result) => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch((error) => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });

#!/usr/bin/env node
// Task-local equivalent of email-api scripts/email-contacts.js
// Uses only Node built-ins (no minimist dependency).

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token.startsWith('--')) {
      const key = token.slice(2);
      const value = argv[i + 1];
      args[key] = value !== undefined && !value.startsWith('--') ? value : true;
      if (value !== undefined && !value.startsWith('--')) i++;
    }
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgs(process.argv.slice(2));

getContacts(args)
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
